const keyLight = new THREE.DirectionalLight(0xfff5e6, 1.2);
keyLight.position.set(8, 12, 10);
keyLight.castShadow = true;
keyLight.shadow.mapSize.width = 2048;
keyLight.shadow.mapSize.height = 2048;

const fillLight = new THREE.DirectionalLight(0xd6e6ff, 0.6);
fillLight.position.set(-10, 5, 8);

const rimLight = new THREE.PointLight(0xaaccff, 0.5, 30);
rimLight.position.set(-6, 4, -8);

scene.add(new THREE.AmbientLight(0x7f8aa6, 0.35), keyLight, fillLight, rimLight);
scene.fog = new THREE.Fog(0xf4f7fb, 20, 90);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.minDistance = 10;
controls.maxDistance = 80;

camera.position.set(28, 22, 38);
camera.lookAt(0, 0, 0);

function createParticleTexture() {
  const canvas = document.createElement('canvas');
  canvas.width = 64;
  canvas.height = 64;
  const ctx = canvas.getContext('2d');
  const gradient = ctx.createRadialGradient(32, 32, 0, 32, 32, 32);
  gradient.addColorStop(0, 'rgba(255, 255, 255, 1)');
  gradient.addColorStop(0.4, 'rgba(255, 255, 255, 0.5)');
  gradient.addColorStop(1, 'rgba(255, 255, 255, 0)');
  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, 64, 64);
  const texture = new THREE.CanvasTexture(canvas);
  texture.needsUpdate = true;
  return texture;
}

function createGlowTexture() {
  const canvas = document.createElement('canvas');
  canvas.width = 128;
  canvas.height = 128;
  const ctx = canvas.getContext('2d');
  const gradient = ctx.createRadialGradient(64, 64, 0, 64, 64, 64);
  gradient.addColorStop(0, 'rgba(255, 240, 200, 1)');
  gradient.addColorStop(0.2, 'rgba(255, 220, 150, 0.4)');
  gradient.addColorStop(0.5, 'rgba(255, 200, 100, 0.1)');
  gradient.addColorStop(1, 'rgba(255, 200, 100, 0)');
  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, 128, 128);
  return new THREE.CanvasTexture(canvas);
}

const galaxyGroup = new THREE.Group();
scene.add(galaxyGroup);

const galaxyParams = {
  count: 15000,
  arms: 4,
  radius: 32,
  spin: 0.75,
  randomness: 0.5,
  coreRadius: 3.5,
  coreCount: 4000
};

const coreGeometry = new THREE.BufferGeometry();
const corePositions = [];
const coreColors = [];
const coreSizes = [];

for (let i = 0; i < galaxyParams.coreCount; i++) {
  const r = Math.random() * galaxyParams.coreRadius;
  const theta = Math.random() * Math.PI * 2;
  const phi = Math.acos(2 * Math.random() - 1);

  const x = r * Math.sin(phi) * Math.cos(theta);
  const y = r * Math.sin(phi) * Math.sin(theta) * 0.25;
  const z = r * Math.cos(phi);

  corePositions.push(x, y, z);

  const color = new THREE.Color();
  color.setHSL(0.12 + Math.random() * 0.08, 0.8, 0.85 + Math.random() * 0.15);
  coreColors.push(color.r, color.g, color.b);
  coreSizes.push(1.0 + Math.random() * 0.9);
}

coreGeometry.setAttribute('position', new THREE.Float32BufferAttribute(corePositions, 3));
coreGeometry.setAttribute('color', new THREE.Float32BufferAttribute(coreColors, 3));
coreGeometry.setAttribute('size', new THREE.Float32BufferAttribute(coreSizes, 1));

const coreMaterial = new THREE.PointsMaterial({
  size: 1.0,
  vertexColors: true,
  map: createParticleTexture(),
  blending: THREE.AdditiveBlending,
  depthWrite: false,
  transparent: true,
  opacity: 0.95,
  sizeAttenuation: true
});

const coreSystem = new THREE.Points(coreGeometry, coreMaterial);
galaxyGroup.add(coreSystem);

const armGeometry = new THREE.BufferGeometry();
const armPositions = [];
const armColors = [];
const armSizes = [];

for (let i = 0; i < galaxyParams.count; i++) {
  const armIndex = i % galaxyParams.arms;
  const armAngle = (armIndex / galaxyParams.arms) * Math.PI * 2;
  const r = galaxyParams.coreRadius + Math.pow(Math.random(), 0.8) * (galaxyParams.radius - galaxyParams.coreRadius);
  const spiralAngle = r * galaxyParams.spin;
  const angle = armAngle + spiralAngle + (Math.random() - 0.5) * galaxyParams.randomness;

  const diskThickness = 0.4 + r * 0.06;
  const y = (Math.random() - 0.5) * diskThickness * Math.exp(-r / galaxyParams.radius * 2);

  const x = Math.cos(angle) * r;
  const z = Math.sin(angle) * r;

  armPositions.push(x, y, z);

  const color = new THREE.Color();
  const distNorm = r / galaxyParams.radius;

  if (Math.random() > 0.88) {
    color.setHSL(0.04 + Math.random() * 0.06, 0.7, 0.25 + Math.random() * 0.15);
  } else if (distNorm < 0.25) {
    color.setHSL(0.15 - distNorm * 0.1, 0.75, 0.75);
  } else {
    color.setHSL(0.62 - distNorm * 0.15, 0.55, 0.65 + Math.random() * 0.15);
  }
  armColors.push(color.r, color.g, color.b);

  let size = 0.35;
  if (r < galaxyParams.coreRadius * 2) size = 0.7;
  else size = 0.25 + (1 - distNorm) * 0.35;
  armSizes.push(size + Math.random() * 0.15);
}

armGeometry.setAttribute('position', new THREE.Float32BufferAttribute(armPositions, 3));
armGeometry.setAttribute('color', new THREE.Float32BufferAttribute(armColors, 3));
armGeometry.setAttribute('size', new THREE.Float32BufferAttribute(armSizes, 1));

const armMaterial = new THREE.PointsMaterial({
  size: 0.5,
  vertexColors: true,
  map: createParticleTexture(),
  blending: THREE.AdditiveBlending,
  depthWrite: false,
  transparent: true,
  opacity: 0.9,
  sizeAttenuation: true
});

const armSystem = new THREE.Points(armGeometry, armMaterial);
galaxyGroup.add(armSystem);

const coreGlow = new THREE.Sprite(new THREE.SpriteMaterial({
  map: createGlowTexture(),
  color: 0xffaa44,
  blending: THREE.AdditiveBlending,
  transparent: true,
  opacity: 0.85,
  depthWrite: false
}));
coreGlow.scale.set(10, 10, 10);
galaxyGroup.add(coreGlow);

const referencePlane = new THREE.Mesh(
  new THREE.PlaneGeometry(180, 180),
  new THREE.MeshBasicMaterial({ color: 0xe8eef5, transparent: true, opacity: 0.12, side: THREE.DoubleSide })
);
referencePlane.rotation.x = -Math.PI / 2;
referencePlane.position.y = -12;
scene.add(referencePlane);

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  galaxyGroup.rotation.y = t * 0.06;
  galaxyGroup.rotation.z = Math.sin(t * 0.15) * 0.04;
  galaxyGroup.rotation.x = Math.cos(t * 0.12) * 0.025;

  const pulse = 0.85 + Math.sin(t * 1.2) * 0.08;
  coreGlow.material.opacity = pulse;
  const scale = 10 + Math.sin(t * 1.0) * 0.4;
  coreGlow.scale.set(scale, scale, scale);

  rimLight.intensity = 0.45 + Math.sin(t * 0.7) * 0.1;

  controls.update();
  renderer.render(scene, camera);
}

animate();

